  "kundali.janma_phala_title": { ne: "जन्मफल तालिका (भाव र ग्रह)", en: "Janma phala tables (by house & graha)" },
  "kundali.janma_phala_tab_male": { ne: "पुरुष", en: "Male (Purush)" },
  "kundali.janma_phala_tab_female": { ne: "स्त्री", en: "Female (Stree)" },
  "kundali.janma_phala_tabs_aria": { ne: "पुरुष वा स्त्री जन्मफल तालिका", en: "Purush or Stree janma table" },
  "kundali.janma_phala_purusha_intro": {
    ne: "पुरुष जन्म कुण्डली तालिका नेपाली ज्योतिष परम्परामा पुरुषहरूको जन्मकुण्डलीमा १२ भाव (तनु, धन, भ्राता, सुख, पुत्र, रिपु, कलत्र, आयु, धर्म, कर्म, आय र व्यय) मा बसेका नौ ग्रह र छाया उपग्रह 'गुलिक' को शास्त्रोक्त फल बताउने तालिका हो। नेपाली पण्डितहरूले पुरुषको जन्मकुण्डली विश्लेषण गर्दा प्रत्येक ग्रह कुन भावमा छ र त्यसले धन, पराक्रम, रोजगार, बुद्धि, आयु, र स्वास्थ्यमा के प्रभाव पार्छ भन्ने हेर्न यो तालिका प्रयोग गर्छन्। यो परम्परागत जातकोक्तम् फल (शास्त्रीय व्याख्या) मा आधारित छ।",
    en: "Classical phala for the nine grahas and Gulika in each of the twelve houses of a male birth chart — used in Nepali jyotish tradition for wealth, courage, career, longevity, and health (jātakoktaṃ phala).",
  },
  "kundali.janma_phala_stree_intro": {
    ne: "स्त्री जन्म कुण्डली तालिका नेपाली ज्योतिष परम्परामा महिलाहरूको जन्मकुण्डलीमा १२ भावमा बसेका ग्रहहरूको शास्त्रोक्त फल बताउने तालिका हो। यो तालिका विशेष गरी महिला-केन्द्रित जीवन पक्षहरू — सौभाग्य (वैवाहिक सुख), पारिवारिक सुख, सन्तान सुख, र स्वास्थ्य — मा केन्द्रित छ। राहु र केतुलाई एउटै स्तम्भमा समावेश गरिएको छ। यो पनि जातकोक्तम् फल (शास्त्रीय व्याख्या) मा आधारित छ।",
    en: "Classical phala for grahas in each house of a female birth chart — focused on saubhāgya, family, children, and health; Rahu and Ketu share one column (jātakoktaṃ phala).",
  },
  "kundali.janma_phala_purusha_hint": {
    ne: "→ सूर्य: कर्म — कीर्तिमान् | चन्द्र: कलत्र — बहुस्त्रीकः | मङ्गल: व्यय — व्ययी",
    en: "→ Sun: karma — sukīrtimān | Moon: kalatra — bahustrīkaḥ | Mars: vyaya — vyayī",
  },
  "kundali.janma_phala_stree_hint": {
    ne: "→ सूर्य: कर्म — सुकर्मरता | चन्द्र: स्त्री — पतिप्रिया सुदेहा | मङ्गल: व्यय — खला रुगार्ता",
    en: "→ Sun: karma — sukarmaratā | Moon: strī — patipriyā sudehā | Mars: vyaya — khalā rugārtā",
  },
