  "brahma_mana.now_title": { ne: "हामी अहिले कहाँ छौं", en: "Where we are now" },
  "brahma_mana.now_year": {
    ne: "ब्रह्माको {{year}}औं वर्षको पहिलो दिन — दोस्रो परार्ध भर्खर सुरु भएको",
    en: "The first day of year {{year}} of Brahmā's life — the second Parārdha has just begun",
  },
  "brahma_mana.now_kalpa": { ne: "श्वेतवाराह कल्प", en: "Śvetavarāha Kalpa" },
  "brahma_mana.now_manvantara": { ne: "{{n}}औं मन्वन्तर — वैवस्वत", en: "Manvantara {{n}} — Vaivasvata" },
  "brahma_mana.now_mahayuga": { ne: "{{n}}औं महायुग", en: "Mahāyuga {{n}}" },
  "brahma_mana.now_kali": {
    ne: "कलियुगका {{years}} वर्ष बितिसके (इ.पू. ३१०२ देखि)",
    en: "{{years}} years of the Kali Yuga gone (since 3102 BCE)",
  },
  "brahma_mana.now_kalpa_elapsed": { ne: "यस कल्पमा बितेका वर्ष: {{years}}", en: "Years gone in this Kalpa: {{years}}" },
  "brahma_mana.pada_title": { ne: "पादअनुसार युग", en: "The Yugas by pāda" },
  "brahma_mana.pada_caption": {
    ne: "सूर्य सिद्धान्त १.१७: महायुगको दशांश ({{pada}} वर्ष, एक पाद) लाई ४, ३, २ र १ ले गुणन।",
    en: "Surya Siddhanta 1.17: one tenth of the Mahāyuga ({{pada}} years, one pāda) times 4, 3, 2 and 1.",
  },
  "brahma_mana.col_yuga": { ne: "युग", en: "Yuga" },
  "brahma_mana.col_padas": { ne: "पाद", en: "Pādas" },
  "brahma_mana.col_calc": { ne: "हिसाब", en: "Calculation" },
  "brahma_mana.col_years": { ne: "सौर वर्ष", en: "Solar years" },
  "brahma_mana.col_unit": { ne: "एकाइ", en: "Unit" },
  "brahma_mana.col_divya": { ne: "दिव्य वर्ष", en: "Divya varṣa" },
  "brahma_mana.col_roughly": { ne: "लगभग", en: "Roughly" },
  "brahma_mana.pada_note": {
    ne: "प्रत्येक अङ्कमा त्यस युगको सन्ध्या र सन्ध्यांश (प्रत्येक बाह्रौं भाग) समावेश छन्।",
    en: "Each figure includes the yuga's dawn and dusk, a twelfth of it each.",
  },
  "brahma_mana.years_title": { ne: "सौर वर्षमा", en: "In solar years" },
  "brahma_mana.notes_title": { ne: "ध्यान दिनुहोस्", en: "Worth knowing" },
  "brahma_mana.note_month": {
    ne: "ब्रह्म मास एउटा कल्प होइन — यसमा ब्रह्माका ३० दिन-रात पर्छन्।",
    en: "A Brahma month is not one Kalpa: it holds 30 of Brahmā's day-nights.",
  },
  "brahma_mana.note_sandhi": {
    ne: "१४ मन्वन्तर × ७१ = {{core}} महायुग मात्र हुन्छ; बाँकी {{rest}} महायुग १५ सन्धि ({{sandhi}} वर्ष प्रत्येक) ले पुर्‍याउँछन्, र जम्मा {{total}} महायुग बन्छ।",
    en: "14 Manvantaras × 71 make only {{core}} Mahāyugas; the 15 sandhis ({{sandhi}} years each) make up the other {{rest}}, for {{total}} in all.",
  },
  "brahma_mana.note_night": {
    ne: "कल्प ब्रह्माको दिन मात्र हो; रात उत्तिकै लामो हुन्छ, त्यसैले एक दिन-रात {{years}} सौर वर्ष।",
    en: "A Kalpa is Brahmā's daytime only; his night is as long, so one day-night is {{years}} solar years.",
  },
  "brahma_mana.note_year": {
    ne: "ब्रह्म वर्ष ३६० दिन-रातको परम्परागत गणनामा आधारित छ।",
    en: "The Brahma year follows the conventional count of 360 day-nights.",
  },
  "brahma_mana.source": { ne: "स्रोत: सूर्य सिद्धान्त, अध्याय १, श्लोक १५–२४", en: "Source: Surya Siddhanta, chapter 1, verses 15–24" },
