  "dainik.kshaya_notice": {
    ne: "<b>क्षय मास:</b> यो महिना <b>{{month}}</b> क्षय मास हो ({{range}}) — एउटै चान्द्र महिनामा दुई सङ्क्रान्ति परेकाले एक महिनाको नाम लोप भएको छ। {{adhikLine}}",
    en: "<b>Kshaya Maas:</b> this month is the <b>{{month}}</b> kshaya ({{range}}) — two sankrantis fall in a single lunar month, so one month name is dropped. {{adhikLine}}",
  },
  "dainik.kshaya_notice_adhik": {
    ne: "यसअघि र पछि अधिक मास पर्छ: {{adhik}}।",
    en: "It is flanked by adhik months: {{adhik}}.",
  },
  "dainik.adhik_notice": {
    ne: "<b>अधिक मास:</b> यस वर्ष <b>अधिक {{month}}</b> मास परेको छ — त्यसैले यो महिनामा अधिक र शुद्ध पक्षहरू छुट्टाछुट्टै देखाइएका छन्। (अधिक मास = मलमास / पुरुषोत्तम मास; यसमा सङ्क्रान्ति पर्दैन।)",
    en: "<b>Adhik Maas:</b> this year has an <b>Adhik {{month}}</b> month — so the adhik and shuddha pakshas are shown separately for this month. (Adhik Maas = Malamas / Purushottam Maas; it contains no sankranti.)",
  },
  "dainik.legend_note_positions": {
    ne: "प्रत्येक पक्षको आरम्भमा ग्रहहरूको स्पष्ट स्थान अंश°, कला′, विकला″ (र प्रति-विकला) मा दिइन्छ — जस्तै “१३ ६ २९ ४०” = १३ अंश ६ कला २९ विकला ४० प्रति-विकला। <vakri>वक्री</vakri> = उल्टो गति, <margi>मार्गी</margi> = सुल्टो गति।",
    en: "At the start of each paksha, each planet's exact position is given in degrees°, kala′, vikala″ (and prati-vikala) — e.g. “13 6 29 40” = 13 deg 6 kala 29 vikala 40 prati-vikala. <vakri>Vakri</vakri> = retrograde (backward) motion, <margi>Margi</margi> = direct (forward) motion.",
  },
  "dainik.legend_note_dasha": {
    ne: "<b>दशा कोष्ठक:</b> जन्म-समयमा बाँकी विंशोत्तरी दशाको वर्ष/महिना/दिन। <b>समय सुधार:</b> मुद्रणमा “उ” वा “०” जस्ता सङ्केतले शून्य अंश/कला जनाउँछ।",
    en: "<b>Dasha bracket:</b> the years/months/days of Vimshottari dasha remaining at birth. <b>Time correction:</b> in print, symbols like “u” or “0” indicate zero degrees/kala.",
  },
  "dainik.udayast_legend.1.code": { ne: "व.उ.", en: "व.उ." },
  "dainik.udayast_legend.1.full": { ne: "वक्र उदय", en: "Retrograde rising" },
  "dainik.udayast_legend.1.meaning": { ne: "ग्रह वक्र (उल्टो) अवस्थामा उदय भएको।", en: "The planet rises while retrograde (moving backward)." },
  "dainik.udayast_legend.2.code": { ne: "बु.मा.उ.", en: "बु.मा.उ." },
  "dainik.udayast_legend.2.full": { ne: "बुध मार्गी उदय", en: "Mercury direct rising" },
  "dainik.udayast_legend.2.meaning": { ne: "बुध मार्गी (सुल्टो) भएर उदय भएको।", en: "Mercury rises while direct (moving forward)." },
  "dainik.udayast_legend.3.code": { ne: "वृ.व.उ.", en: "वृ.व.उ." },
  "dainik.udayast_legend.3.full": { ne: "बृहस्पति वक्र उदय", en: "Jupiter retrograde rising" },
  "dainik.udayast_legend.3.meaning": { ne: "बृहस्पति (गुरु) वक्र अवस्थामा उदय भएको।", en: "Jupiter rises while retrograde." },
  "dainik.udayast_legend.4.code": { ne: "शु.मा.उ.", en: "शु.मा.उ." },
  "dainik.udayast_legend.4.full": { ne: "शुक्र मार्गी उदय", en: "Venus direct rising" },
  "dainik.udayast_legend.4.meaning": { ne: "शुक्र मार्गी भएर उदय भएको।", en: "Venus rises while direct." },
  "dainik.udayast_legend.5.code": { ne: "श.मा.उ. ७अ.", en: "श.मा.उ. ७अ." },
  "dainik.udayast_legend.5.full": { ne: "शनि मार्गी उदय, ७ अस्त", en: "Saturn direct rising, sets on the 7th" },
  "dainik.udayast_legend.5.meaning": { ne: "शनि मार्गी भएर उदय भएको र ७ गते अस्त हुने।", en: "Saturn rises while direct and sets on the 7th." },
  "dainik.gochar_legend.1.code": { ne: "पापाशाः", en: "पापाशाः" },
  "dainik.gochar_legend.1.meaning": { ne: "पापशान्ति — कुण्डलीका अशुभ (पाप) ग्रहहरूको स्थिति।", en: "Papashanti — position of the malefic (papa) planets in the chart." },
  "dainik.gochar_legend.2.code": { ne: "सू२", en: "सू२" },
  "dainik.gochar_legend.2.meaning": { ne: "सूर्य दोस्रो घर (भाव) मा रहेको।", en: "The Sun is in the second house (bhava)." },
  "dainik.gochar_legend.3.code": { ne: "२७सू३", en: "२७सू३" },
  "dainik.gochar_legend.3.meaning": { ne: "२७ गते सूर्य तेस्रो घरमा प्रवेश गर्ने।", en: "The Sun enters the third house on the 27th." },
  "dainik.gochar_legend.4.code": { ne: "म.१", en: "म.१" },
  "dainik.gochar_legend.4.meaning": { ne: "मंगल पहिलो घरमा रहेको।", en: "Mars is in the first house." },
  "dainik.gochar_legend.5.code": { ne: "श.९", en: "श.९" },
  "dainik.gochar_legend.5.meaning": { ne: "शनि नवौँ घरमा रहेको।", en: "Saturn is in the ninth house." },
  "dainik.gochar_legend.6.code": { ne: "रा.५ के.११", en: "रा.५ के.११" },
  "dainik.gochar_legend.6.meaning": { ne: "राहु पाँचौँ र केतु एघारौँ घरमा रहेको।", en: "Rahu is in the fifth and Ketu in the eleventh house." },

