  "learn.diagrams.hierarchy_step_vaara": { ne: "वार", en: "Vāra" },
  "learn.diagrams.hierarchy_top": { ne: "आकाशीय गति", en: "Celestial motion" },
  "learn.diagrams.hierarchy_wide_aria": {
    ne: "पृथ्वी, सूर्य र चन्द्रको गतिबाट दिन, सौर महिना र चान्द्र मास बन्छन्, र तीनै मिलेर पञ्चाङ्ग र वि.सं. मिति बनाउँछन्।",
    en: "Earth's, the Sun's and the Moon's motions produce the day, the solar month and the lunar month; together they make the panchanga and a Bikram Sambat date.",
  },
  "learn.diagrams.hora_cycle_caption": {
    ne: "सात ग्रह परम्परागत परिक्रमा–कालको क्रममा चक्रमा बस्छन्, र दिनको हरेक घण्टा (होरा) क्रमको अर्को ग्रहले चलाउँछ। एक दिनमा २४ होरा हुन्छन्, र २४ ÷ ७ ले ३ बाँकी छाड्छ — त्यसैले भोलिको पहिलो होरा चक्रमा तीन स्थान अगाडि पर्छ। सूर्यबाट तीन–तीन गन्दै जानुहोस्: सूर्य → चन्द्र → मंगल → बुध → बृहस्पति → शुक्र → शनि। बारको क्रम मनपरी होइन, यही गणनाबाट आएको हो।",
    en: "The seven grahas sit in a ring ordered by classical orbital period, and each hour of the day — each hora — is ruled by the next one along. A day holds 24 horas, and 24 ÷ 7 leaves 3, so tomorrow's first hora lands three places further round. Count in threes from the Sun: Sun → Moon → Mars → Mercury → Jupiter → Venus → Saturn. The weekday order is not arbitrary; it is that arithmetic.",
  },
  "learn.diagrams.hora_cycle_label": {
    ne: "सात ग्रहको होरा चक्र र त्यसबाट निस्कने बारको क्रम",
    en: "The seven-graha hora cycle and the weekday order it generates",
  },
  "learn.diagrams.hora_cycle_remainder": { ne: "२४ ÷ ७ → बाँकी ३", en: "24 ÷ 7 → remainder 3" },
  "learn.diagrams.hora_cycle_step": { ne: "→ ३ स्थान अगाडि", en: "→ 3 places along" },
  "learn.diagrams.hora_ring_jupiter": { ne: "बृहस्पति", en: "Jup" },
  "learn.diagrams.hora_ring_mercury": { ne: "बुध", en: "Mer" },
  "learn.diagrams.hora_ring_saturn": { ne: "शनि", en: "Sat" },
