  "learn.diagrams.local_noon": { ne: "स्थानीय मध्याह्न", en: "local noon" },
  "learn.diagrams.manda_row_manda": { ne: "+ मन्द संस्कार", en: "+ manda correction" },
  "learn.diagrams.manda_row_manda_note": {
    ne: "कक्ष हामीमा केन्द्रित छैन — एक फेरोमा एक लहर",
    en: "orbit not centred on us — one wave per revolution",
  },
  "learn.diagrams.manda_row_mean": { ne: "मध्यम ग्रह", en: "mean planet" },
  "learn.diagrams.manda_row_mean_note": { ne: "एकनास वृत्ताकार गति", en: "uniform circular motion" },
  "learn.diagrams.manda_row_shighra": { ne: "+ शीघ्र संस्कार = स्फुट ग्रह", en: "+ shighra = true planet" },
  "learn.diagrams.manda_row_shighra_note": {
    ne: "हाम्रो आफ्नै गति — यहीँबाट वक्री लूप",
    en: "our own motion — this is where retrograde comes from",
  },
  "learn.diagrams.manda_shighra_caption": {
    ne: "मध्यम ग्रह एकनास गतिले वृत्तमा हिँड्छ — गणना गर्न सजिलो, तर आकाशमा गलत। दुई संस्कारले मिलाउँछन्: मन्द संस्कारले कक्ष हामीमा केन्द्रित नभएको कुरा सम्हाल्छ, जसले एक फेरोमा एउटा लहर दिन्छ; शीघ्र संस्कारले हाम्रो आफ्नै परिक्रमा सम्हाल्छ, र वक्री लूप यहीँबाट निस्कन्छ। दुवै क्रमशः लगाएपछि बाँकी रहन्छ स्फुट ग्रह — वास्तविक स्थिति।",
    en: "A mean planet moves at a dead-constant rate around a circle: easy to compute and wrong on the sky. Two corrections repair it. The manda term accounts for the orbit not being centred on us, giving one wave per revolution; the shighra term accounts for our own orbital motion, and that is where the retrograde loop comes from. Applied in turn they leave the true position — the sphuta graha.",
  },
  "learn.diagrams.manda_shighra_label": {
    ne: "मध्यम ग्रहमा मन्द र शीघ्र संस्कार थपेर स्फुट ग्रह",
    en: "Manda and shighra corrections turning a mean planet into a true one",
  },
  "learn.diagrams.moonrise_none": { ne: "यो दिन चन्द्रोदय छैन", en: "no moonrise this day" },
  "learn.diagrams.moonrise_slip_caption": {
    ne: "चन्द्रमा आफ्नै कक्षमा दैनिक ~१३° सर्ने भएकाले लगातार दुई चन्द्रोदयबीच ~२४ घण्टा ५० मिनेट लाग्छ — अर्थात् एक दिनभन्दा सधैँ बढी। त्यसैले ढिलाइ जम्मा हुँदै गएर कुनै दिन पूरै नाघ्छ र त्यो दिन चन्द्रोदयै हुँदैन। उल्टो भने सम्भव छैन: अन्तराल २४ घण्टाभन्दा लामो हुनाले एउटै दिनमा दुई चन्द्रोदय कहिल्यै पर्दैनन्।",
    en: "The Moon moves about 13° along its own orbit each day, so successive moonrises are about 24h 50m apart — always more than one civil day. The slip therefore accumulates until it steps clean over a day, which then has no moonrise at all. The reverse cannot happen: because the interval exceeds 24 hours, two moonrises never fall inside one day.",
  },
  "learn.diagrams.moonrise_slip_label": {
    ne: "चन्द्रोदय हरेक दिन ~५० मिनेट ढिलो — कुनै दिन दुई पटक, कुनै दिन एकै पटक पनि होइन",
    en: "Moonrise slips ~50 minutes a day — some days get two, some get none",
  },
  "learn.diagrams.one_civil_day": { ne: "एक दिन", en: "one civil day" },
  "learn.diagrams.one_revolution_axis": { ne: "एक परिक्रमा →", en: "one revolution →" },
  "learn.diagrams.orbit_aphelion": { ne: "अपसौर (टाढा)", en: "Aphelion (farthest)" },
