  "learn.study.circumpolar.aria": {
    ne: "काठमाडौँको अक्षांशबाट आकाश — कुन तारा कहिल्यै अस्ताउँदैनन् र कुन कहिल्यै उदाउँदैनन्",
    en: "The sky from Kathmandu's latitude — which stars never set and which never rise",
  },
  "learn.study.circumpolar.caption": {
    ne: "आकाशी ध्रुव क्षितिजभन्दा ठ्याक्कै अक्षांश जति (काठमाडौँमा २७.७°) माथि हुन्छ, र हरेक तारा त्यही अक्षको वरिपरि वृत्त काट्छ। वृत्त पूरै क्षितिजमाथि परे तारा कहिल्यै अस्ताउँदैन; पूरै तल परे कहिल्यै उदाउँदैन। काठमाडौँको सीमा ±६२.३° हो — सप्तर्षि र क्रक्स दुवै यही सीमाको छेउछाउ पर्छन्, त्यसैले सप्तर्षिको पुच्छर वर्षको केही समय क्षितिजमुनि जान्छ र क्रक्सको माथिल्लो तारा दक्षिणी क्षितिजमा अलिकति देखिन्छ।",
    en: "The celestial pole stands above the horizon by exactly the observer's latitude — 27.7° at Kathmandu — and every star circles that axis. A circle entirely above the horizon never sets; entirely below, it never rises. Kathmandu's limits are ±62.3°, and both the Saptarishi and Crux straddle them: the Dipper's tail dips below the horizon for part of the year, and the top of Crux does clear the southern horizon by a few degrees.",
  },
  "learn.study.circumpolar.celestial_pole": { ne: "खगोलीय ध्रुव", en: "celestial pole" },
  "learn.study.circumpolar.crux_range": { ne: "क्रक्स: क्रान्ति −५७° … −६३°", en: "Crux: dec −57° … −63°" },
  "learn.study.circumpolar.horizon": { ne: "क्षितिज", en: "horizon" },
  "learn.study.circumpolar.never_rises": {
    ne: "क्रान्ति < −६२.३° — कहिल्यै उदाउँदैन",
    en: "dec < −62.3° — never rises",
  },
  "learn.study.circumpolar.never_sets": {
    ne: "क्रान्ति > +६२.३° — कहिल्यै अस्ताउँदैन",
    en: "dec > +62.3° — never sets",
  },
  "learn.study.circumpolar.north": { ne: "उत्तर", en: "N" },
  "learn.study.circumpolar.rises_and_sets": { ne: "बीचमा — उदाउँछ र अस्ताउँछ", en: "in between — rises and sets" },
  "learn.study.circumpolar.saptarishi_range": {
    ne: "सप्तर्षि: क्रान्ति +४९° … +६२°",
    en: "Saptarishi: dec +49° … +62°",
  },
  "learn.study.circumpolar.south": { ne: "दक्षिण", en: "S" },
  "learn.study.declination.aria": {
    ne: "सूर्यको क्रान्ति वर्षभरि — विषुवमा शून्य, अयनान्तमा चरम",
    en: "The Sun's declination through the year — zero at the equinoxes, extreme at the solstices",
  },
  "learn.study.declination.caption": {
    ne: "एउटै वक्र, दुई फरक बिन्दु — विषुव त्यहाँ जहाँ वक्रले शून्य काट्छ (सूर्य विषुवत् रेखामा, दिन–रात बराबर, उत्तर–दक्षिण गति सबैभन्दा छिटो), अयनान्त त्यहाँ जहाँ वक्र फर्किन्छ (क्रान्ति ±२३.४४°, सबैभन्दा लामो र छोटो दिन)। तल वि.सं. महिना — चारै बिन्दु महिनाको सीमामा पर्दैनन्, र शताब्दीयौँमा सर्दै जान्छन्।",
    en: "One curve, two different points — an equinox is where it crosses zero (the Sun on the celestial equator, day equal to night, north–south motion at its fastest); a solstice is where it turns (declination ±23.44°, the longest and shortest day). The B.S. months run underneath: none of the four lands on a month boundary, and over centuries they drift against them.",
  },
  "learn.study.declination.dakshinayana": { ne: "दक्षिणायन", en: "Dakshinayana" },
  "learn.study.declination.uttarayana": { ne: "उत्तरायण", en: "Uttarayana" },
