  "learn.study.equinox.slider": {
    ne: "वर्ष — अक्ष-चलनले विषुव सर्छ (वि.सं. {{from}} → {{to}}; एक पूरा फेरो ~{{cycle}} वर्ष)",
    en: "Year — precession shifts the equinox (BS {{from}} → {{to}}; one full turn ≈ {{cycle}} years)",
  },
  "learn.study.history.era_bbse": { ne: "पू.वि.सं.", en: "BBSE" },
  "learn.study.history.era_bs": { ne: "वि.सं.", en: "BS" },
  "learn.study.history.era_bs_today": { ne: "(आज {{year}})", en: "(today {{year}})" },
  "learn.study.history.lede": {
    ne: "८,८०० वर्ष पुरानो वैदिक पञ्चाङ्ग परम्परा — {{epoch}} को ग्रहसंयोगदेखि युग चक्र, नक्षत्र स्थानान्तरण, र विश्वका पात्रोहरूमा प्रभावसम्म। सबै मिति पू.वि.सं. (~३०००–५८ ई.पू.) वा वि.सं. (५७ ई.पू. देखि) मा प्रस्तुत।",
    en: "An 8,800-year-old Vedic panchanga tradition — from the planetary conjunction of {{epoch}} through the yuga cycles and the shift of the nakshatras, to its influence on calendars around the world. All dates are given in BBSE (~3000–58 BCE) or BS (from 57 BCE).",
  },
  "learn.study.history.toc_aria": { ne: "इतिहासका विषय", en: "History topics" },
  "learn.study.history.toc_title": { ne: "विषयसूची", en: "Contents" },
  "learn.study.history.topics": { ne: "विषयहरू", en: "Topics" },
  "learn.study.history.transcript_lead": { ne: "यो अध्याय", en: "This chapter is a Nepali transcript of the" },
  "learn.study.history.transcript_link": { ne: "वृत्तचित्र", en: "documentary" },
  "learn.study.history.transcript_rest": {
    ne: " को नेपाली प्रतिलेख हो — शैक्षिक उद्देश्यका लागि। विज्ञान र इतिहासका दावीहरू स्वतन्त्र रूपमा प्रमाणित गर्न सिफारिस गरिन्छ।",
    en: ", published here for educational purposes. Readers are encouraged to verify its scientific and historical claims independently.",
  },
  "learn.study.lunar_gap.after_years": { ne: "{{years}} वर्षपछि", en: "after {{years}} yr" },
  "learn.study.lunar_gap.aria": {
    ne: "चान्द्र वर्ष सौर वर्षभन्दा वर्षेनि ११ दिन छोटो — तीन वर्षमा फरक एक महिना नाघ्छ",
    en: "A lunar year falls 11 days short of a solar year — in three years the gap exceeds a month",
  },
  "learn.study.lunar_gap.caption": {
    ne: "बाह्र चान्द्र मास ३५४.४ दिनको हुन्छ, सौर वर्ष ३६५.२४ — हरेक वर्ष १०.८७ दिनको घाटा। घाटा जम्मा हुँदै जान्छ, र तेस्रो वर्षसम्ममा ३२.६ दिन पुग्छ, जुन एउटा चान्द्र मासभन्दै लामो। त्यही बेला एक अधिक मास थपेर हिसाब मिलाइन्छ — यही चान्द्र–सौर पात्रोको मूल व्यवस्था हो।",
    en: "Twelve lunar months make 354.4 days against a solar year of 365.24 — a shortfall of 10.87 days each year. It accumulates, and by the third year it reaches 32.6 days, longer than a lunar month itself. That is when an extra month is inserted to settle the account — the central mechanism of a lunisolar calendar.",
  },
  "learn.study.lunar_gap.legend_drift": { ne: "फरक {{days}} दिन/वर्ष", en: "gap {{days}} d/yr" },
  "learn.study.lunar_gap.legend_lunar_months": { ne: "१२ चान्द्र मास ३५४.४", en: "12 lunar months 354.4" },
  "learn.study.lunar_gap.legend_solar_year": { ne: "सौर वर्ष ३६५.२४", en: "solar year 365.24" },
  "learn.study.lunar_gap.three_year_total": {
    ne: "३ वर्षमा {{days}} दिन — एक चान्द्र मासभन्दा लामो → अधिक मास",
    en: "{{days}} days in 3 years — longer than a lunar month → adhika māsa",
  },
  "learn.study.medium": { ne: "मध्यम", en: "Medium" },
  "learn.study.month_lengths.aphelion": { ne: "अपसौर — सूर्य ढिलो", en: "aphelion — Sun slowest" },
  "learn.study.month_lengths.aria": {
    ne: "बाह्र नेपाली महिनाको लम्बाइ — उपसौर नजिक छोटो, अपसौर नजिक लामो",
    en: "The lengths of the twelve Nepali months — short near perihelion, long near aphelion",
  },
  "learn.study.month_lengths.caption": {
    ne: "एक सौर मास भनेको दिनको गन्ती होइन — राशि पट्टीमा सूर्यले पार गर्ने ३०° हो। उपसौर नजिक (पुष–माघ) सूर्य छिटो हिँड्छ, त्यसैले ती ३० अंश कम दिनमै सकिन्छन्; अपसौर नजिक (असार) ढिलो, र महिना लामो हुन्छ। यही कारण नेपाली महिना २९ देखि ३२ दिनसम्मको हुन्छ।",
    en: "A solar month is not a count of days but 30° of the Sun's travel along the zodiac. Near perihelion (Poush–Magh) the Sun moves fastest, so those 30° take fewer days; near aphelion (Asar) it is slowest and the month stretches. That is why a Nepali month runs anywhere from 29 to 32 days.",
  },
  "learn.study.month_lengths.perihelion": { ne: "उपसौर — सूर्य छिटो", en: "perihelion — Sun fastest" },
  "learn.study.orbit.autumnal_equinox": { ne: "शरद विषुव", en: "Autumnal equinox" },
  "learn.study.orbit.caption_direction": { ne: "वामावर्त", en: "counter-clockwise" },
  "learn.study.orbit.caption_lead": {
    ne: "सूर्य एउटा केन्द्रबिन्दु (focus) मा छ — पृथ्वी वास्तविक दीर्घवृत्तमा",
    en: "The Sun sits at one focus — Earth orbits the true ellipse",
  },
  "learn.study.orbit.caption_rest": {
    ne: "घुम्छ। नजिक हुँदा छिटो (उपसौर / हिमतिर), टाढा हुँदा ढिलो (अपसौर / ग्रीष्मतिर) — यसैले केही महिनामा दिन छिटो बित्छ। ध्रुव {{tilt}}° ढल्किएकाले सङ्क्रान्तिमा लामो/छोटो दिन र विषुवमा बराबर दिन–रात हुन्छ।",
    en: "Faster when near (perihelion / around winter), slower when far (aphelion / around summer) — which is why some months pass more quickly. Because the pole is tilted {{tilt}}°, solstices give long and short days while equinoxes give equal day and night.",
  },
