  "learn.study.two_systems.sidereal_lap_remaining": {
    ne: "३६०° सम्म {{degrees}}° बाँकी",
    en: "{{degrees}}° to the 360° lap",
  },
  "learn.study.two_systems.sidereal_vs_synodic": {
    ne: "एक फेरो — नक्षत्र मास — ठ्याक्कै ३६०°, २७.३ दिन। तर त्यतिन्जेल पृथ्वी सूर्यवरिपरि ~२९° सरिसक्छ, त्यसैले चन्द्र फेरि सूर्यको छेउमा पुग्दैन; भेट्न अझै ~२९° चाहिन्छ। त्यही हो चान्द्र मास: ~३८९°, २९.५ दिन। कक्षमा पहिलो फेरो भित्री रेखा, त्यसपछिको बढी भाग बाहिरी हरियो चापमा देखिन्छ।",
    en: "One lap — the sidereal month — is exactly 360° in 27.3 days. By then Earth has moved ~29° around the Sun, so the Moon is not beside the Sun again; it needs ~29° more to catch up. That is the synodic month: ~389° in 29.5 days. On the orbit, the first lap is the inner line and the overshoot is the outer green arc.",
  },
  "learn.study.two_systems.solar_month_gate": { ne: "सौर महिना · गते", en: "Solar month · gate" },
