  /* ── ui.learn ───────────────────────────────────────────────────────────── */
  "ui.learn.a_solar_month_is_not_a": {
    ne: "सौर महिना दिनको गन्ती होइन — यो राशि पट्टीमा सूर्यको ३०° यात्रा हो। पृथ्वीको कक्ष अण्डाकार भएकाले उपसौर (पुष–माघ) नजिक सूर्यको देखिने गति छिटो हुन्छ, त्यसैले त्यो ३०° छिटो पार हुन्छ — छोटो महिना। अपसौर (असार) नजिक गति सुस्त हुन्छ — लामो महिना। यो तथ्याङ्क पात्रोले नै प्रयोग गर्ने तालिकाबाटै आएको हो।",
    en: "A solar month is not a count of days — it is 30° of the Sun's travel along the rashi belt. Because Earth's orbit is elliptical, the Sun's apparent motion is fastest near perihelion (Poush–Magh), so that 30° passes quickly — a short month. Near aphelion (Asar) it crawls — a long month. This data comes from the same table the patro itself uses.",
  },
  "ui.learn.a_solar_month_sankranti_to_sankranti": {
    ne: "सौर मास (सङ्क्रान्तिदेखि सङ्क्रान्तिसम्म) ~३०.४ दिनको हुन्छ, चान्द्र मास (औंसीदेखि औंसीसम्म) ~२९.५ दिनको — हरेक चक्रमा चान्द्र मास छोटो हुँदै जान्छ। समय बित्दै जाँदा कुनै एउटा चान्द्र महिनाभित्र कुनै सङ्क्रान्ति नै पर्दैन — त्यो महिनाको आफ्नै सौर महिना हुँदैन, त्यसैले त्यसले पछिको महिनाको नाम लिन्छ, अगाडि 'अधिक' जोडेर।",
    en: "A solar month (sankranti to sankranti) runs ~30.4 days; a lunar month (amavasya to amavasya) runs ~29.5 days — the lunar month keeps landing slightly earlier each cycle. Eventually one lunar month contains no sankranti at all — it has no solar month of its own, so it borrows the name of the one after it, with 'adhik' (extra) in front.",
  },
  "ui.learn.a_tithi_can_begin_and_end": {
    ne: "तिथि दिनको जुनसुकै समयमा सुरु वा सकिन सक्छ, तर पात्रोले दिनको एउटै लेबल चाहिन्छ। यहाँ तिथि ०४:३० मा बद्लिन्छ — सूर्योदयभन्दा (०५:४५) अघि — त्यसैले सूर्योदयमा चलिरहेको तिथि चतुर्थी नै त्यो दिनको तिथि हुन्छ, तृतीया एक क्षण पनि दिन पाउँदैन।",
    en: "A tithi can begin and end at any hour, but the calendar needs one label per day. Here the tithi changes at 04:30 — before sunrise (05:45) — so the tithi running at sunrise, Chaturthi, is the one that day gets; Tritiya never gets a day of its own.",
  },
  "ui.learn.a_tithi_ends_at_one_absolute": {
    ne: "तिथि सिंगो पृथ्वीका लागि एउटै क्षणमा सकिन्छ। फरक पर्ने कुरा हो — त्यो क्षण प्रत्येक ठाउँको सूर्योदयको सापेक्ष कहाँ पर्छ। काठमाडौँमा सीमा सूर्योदयअघि पर्छ, त्यसैले त्यो दिनले अर्को तिथि लिन्छ; सिड्नीमा सीमा सूर्योदयपछि पर्छ, त्यसैले त्यो दिनले अघिल्लै तिथि राख्छ। दुवै सही छन् — कारण सूर्योदय नियम हो, खगोलशास्त्रमा भिन्नता होइन।",
    en: "A tithi ends at one absolute instant for the whole planet. What differs is where that instant falls relative to each place's own sunrise. At Kathmandu the boundary falls before sunrise, so that day takes the next tithi; at Sydney it falls after sunrise, so that day keeps the earlier one. Both are correct — the reason is the sunrise rule, not a difference in the astronomy.",
  },
