  "ui.learn.equinox_tropical": { ne: "विषुव (सायन)", en: "Equinox (tropical)" },
  "ui.learn.equinox_zero_crossing": { ne: "विषुव — शून्य काट्ने ठाउँ", en: "Equinox — zero crossing" },
  "ui.learn.equinoxes": { ne: "विषुव", en: "Equinoxes" },
  "ui.learn.equinoxes_and_solstices_are_different_points": {
    ne: "विषुव र अयनान्त एउटै वक्रका फरक बिन्दु हुन्, अदलाबदली गर्न मिल्दैनन्। विषुव भनेको वक्रले शून्य काट्ने ठाउँ हो — सूर्य खगोलीय विषुवत् रेखामा हुन्छ, गति सबैभन्दा छिटो। अयनान्त भनेको वक्र घुम्ने ठाउँ हो — सूर्यको उत्तर–दक्षिण गति ±२३.४४° मा रोकिन्छ र उल्टिन्छ।",
    en: "Equinoxes and solstices are different points on the same curve, not interchangeable. An equinox is where the curve crosses zero — the Sun is on the celestial equator, moving fastest north-south. A solstice is where the curve turns — the Sun's north-south motion halts at ±23.44° and reverses.",
  },
  "ui.learn.exit_fullscreen": { ne: "बन्द गर्नुहोस्", en: "Exit fullscreen" },
  "ui.learn.extra_rotation": { ne: "अतिरिक्त घूर्णन", en: "Extra rotation" },
  "ui.learn.first_quarter": { ne: "अष्टमी", en: "First quarter" },
  "ui.learn.frame_rate": { ne: "फ्रेम दर", en: "Frame rate" },
  "ui.learn.from_amavasya_0_dark_through_purnima": {
    ne: "औंसी (कोण ०°, अन्धकार) देखि पूर्णिमा (कोण १८०°, पूर्ण उज्यालो) हुँदै फेरि अर्को औंसीसम्म — सातवटा नामाकरण गरिएका बिन्दु। प्रत्येक चन्द्र साँचो सूर्य-कोणबाट उज्यालो पारिएको छ, त्यसैले आकार कोरिएको होइन — गणना गरिएको हो।",
    en: "From Amavasya (0°, dark) through Purnima (180°, fully lit) to the next Amavasya — seven named points along the way. Each Moon is lit from its true Sun-elongation angle, so the shape is computed, not drawn.",
  },
