  "ui.learn.pope_gregory_xiii_decreed_that_october": {
    ne: "पोप ग्रेगोरी १३ ले १५८२ मा अक्टोबर ४ पछि सिधै अक्टोबर १५ लागू गरे — बीचका १० दिन क्यालेन्डरबाट हराए (हप्ताको क्रम भने अटुट रह्यो — बिहीबार पछि सिधै शुक्रबार)। हरेक देशले फरक-फरक समयमा अपनायो, र जति ढिलो अपनायो त्यति धेरै दिन हराउनुपर्‍यो — किनकि जुलियन र ग्रेगोरियनबीचको फरक हरेक शताब्दीको हिसाबले बढ्दै गयो।",
    en: "Pope Gregory XIII decreed that October 4, 1582 was followed directly by October 15 — the ten days in between vanished from the calendar (the weekday sequence stayed unbroken — Thursday was followed straight by Friday). Different countries adopted the reform at different times, and the later they switched, the more days they had to drop — the Julian–Gregorian gap kept growing with every century.",
  },
