  "ui.onboarding.x_3c35ba8e": { ne: "अर्को स्क्रिनमा कुन वर्षदेखि कुन वर्षसम्म चाहिने छान्नुहोस् (बढीमा ९० वर्षको अन्तर)। डाउनलोड सुरु गर्नु अघि कति डाटा लाग्छ देखाइनेछ। · Next, choose which years you need (at most a 90-year span). You'll see how much data it takes before anything downloads.", en: "Next, choose which years you need (at most a 90-year span). You'll see how much data it takes before anything downloads." },
